    },
    {
      "bodyElementIndex": 15,
      "tag": "p",
      "completeText": ""
    },
    {
      "bodyElementIndex": 16,
      "tag": "li",
      "completeText": "Daripada Anas bin Malik RA berkata: Adapun Nabi SAW banyak membaca:"
